const colors = ['海蓝','琥珀','翡翠','紫晶','樱桃','月白','薄荷','珊瑚','靛青','金橙'];
const colorsEn = ['Ocean Blue','Amber','Jade','Amethyst','Cherry','Moon White','Mint','Coral','Indigo','Golden Orange'];
const patterns = ['流纹','涟漪','星砂','花瓣','幻彩'];
const patternsEn = ['Swirl','Ripple','Stardust','Petals','Iridescence'];
colors.forEach((c,i)=>patterns.forEach((p,j)=>{EN[c+p]=`${colorsEn[i]} ${patternsEn[j]}`;}));
const plural = (n:string, word:string)=>`${n} ${word}${Number(n)===1?'':'s'}`;
const templates: [RegExp, (...args:string[])=>string][] = [
 [/^第 (\d+) 关$/,n=>`Level ${n}`],
 [/^目标 (\d+)\/(\d+)(?:\s+剩余 (\d+) 次)?$/,(n,total,shots)=>`Target ${n}/${total}${shots===undefined?'':`   Shots Left: ${shots}`}`],
 [/^剩余 (\d+) 次(?:机会)?$/,n=>`Shots Left: ${n}`],
 [/^目标 (\d+) 颗$/,n=>`Target: ${n}`],
 [/^完成 (\d+) 个目标$/,n=>`Knock out ${plural(n,'target')}`],
 [/^收藏图鉴\s+(\d+)\/(\d+)$/,(n,total)=>`Collection ${n}/${total}`],
 [/^已收藏 (\d+) \/ (\d+) · 击出并过关后解锁$/,(n,total)=>`Collected ${n}/${total} · Knock out and win to collect`],
 [/^击出 (\d+) \/ (\d+) 颗 · (\d+) 次机会$/,(n,total,shots)=>`Target ${n}/${total} · ${plural(shots,'shot')}`],
 [/^三星 ≤ (\d+) 次  ·  两星 ≤ (\d+) 次$/,(a,b)=>`3 stars ≤ ${plural(a,'shot')} · 2 stars ≤ ${plural(b,'shot')}`],
 [/^击出 (\d+) 颗 · 使用 (\d+) 次射击$/,(n,shots)=>`${plural(n,'marble')} out · ${plural(shots,'shot')} used`],
 [/^新收藏 \+(\d+)  ·  最佳 (\d+) 星$/,(n,stars)=>`New +${n} · Best: ${plural(stars,'star')}`],
 [/^(#\d+\s+·\s+)(.+)$/,(prefix,r)=>prefix+(EN[r]||r)],
 [/^(.+)  ([123]\/3)$/,(title,page)=>(EN[title]||title)+`  ${page}`],
];
export function translate(text:string, language:Language):string {
 if(language==='zh'||!text)return text;
 if(EN[text])return EN[text];
 for(const [pattern,format] of templates){const match=text.match(pattern);if(match)return format(...match.slice(1));}
 return text;
}
